set-variable.value:
@{
        var response = (IResponse)context.Variables["oboResponse"];
        if (response.StatusCode == 429) { return "obo_throttled"; }
        var json = response.Body.As<JObject>(preserveContent: true);
        if (json["error"]?.Type != JTokenType.String) { return "obo_invalid_response"; }
        var error = (string)json["error"];
        if (new [] { "invalid_grant", "interaction_required", "consent_required", "login_required" }.Contains(error)) {
          return "graph_user_action_required";
        }
        if (new [] { "invalid_client", "unauthorized_client", "invalid_scope" }.Contains(error)) {
          return "obo_configuration_error";
        }
        return "obo_unavailable";
      }

@{
        var contract = JObject.Parse((string)context.Variables["graphContract"]);
        var fallback = (int)contract["defaultRetryAfterSeconds"];
        int seconds;
        return Int32.TryParse(((IResponse)context.Variables["oboResponse"]).Headers.GetValueOrDefault("Retry-After", fallback.ToString()), out seconds)
          ? Math.Max(1, Math.Min((int)contract["maximumRetryAfterSeconds"], seconds)) : fallback;
      }

return-response.set-body:
@{
          var status = (int)context.Variables["oboStatus"];
          return new JObject(
            new JProperty("type", "about:blank"),
            new JProperty("title", status == 403 ? "Graph consent or interactive sign-in is required. Verify downstream delegated consent and Conditional Access." : "Delegated token exchange is unavailable."),
            new JProperty("status", status),
            new JProperty("code", (string)context.Variables["oboFailureCode"])
          ).ToString(Newtonsoft.Json.Formatting.None);
        }

set-variable.value:
@{
    var json = ((IResponse)context.Variables["oboResponse"]).Body.As<JObject>(preserveContent: true);
    if (json["access_token"]?.Type != JTokenType.String || json["token_type"]?.Type != JTokenType.String
      || (string)json["token_type"] != "Bearer") { return ""; }
    var token = (string)json["access_token"];
    var contract = JObject.Parse((string)context.Variables["graphContract"]);
    return String.IsNullOrWhiteSpace(token) || token.Length > (int)contract["maximumAccessTokenLength"] ? "" : token;
  }
